<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data-io</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # SQLite and migrations</span></span>
